def calculate_discount(price: float, rate: float) -> float:
    """Calculates net price after applying percentage discount."""
    if not 0.0 <= rate <= 1.0:
        raise ValueError('Rate must be between 0 and 1')
    return round(price * (1 - rate), 2)

