import re

def is_valid_hex_color(code: str) -> bool:
    """Checks if a string is a valid 3 or 6 hex character CSS color code."""
    return bool(re.fullmatch(r'#(?:[0-9a-fA-F]{3}){1,2}', code))

class CircularBuffer:
    def __init__(self, capacity: int):
        self.buffer = [None] * capacity
        self.head = 0
        self.tail = 0
        self.capacity = capacity

def binary_search(arr, target):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
